    "Reciprocity": {"Explanation": "The email offers the recipient a share of the $25 million deposit if they agree to act as the next of kin, creating a sense of reciprocity where the recipient feels they are getting something in return for their involvement."},
    "Scarcity": {"Explanation": "The email implies scarcity by stating that the money will revert to the South African government in 5 years if no one claims it, creating a sense of urgency to act quickly."},
    "Authority": {"Explanation": "The email claims authority through the position of the sender as the Finance Director of STANDARD BANK LTD, suggesting legitimacy and credibility of the offer."},
    "Commitment/Consistency": {"Explanation": "The email does not explicitly reference prior behavior or choices to push further action, so this principle is not present."},
    "Liking": {"Explanation": "The email does not use familiarity, flattery, or personalization to build trust or rapport, so this principle is not present."},
    "Social proof": {"Explanation": "The email does not reference other people's participation or endorsement, so this principle is not present"}
}

