    "Reciprocity": {"Explanation": "The email starts by acknowledging the recipient's technical expertise and their role within the community, creating a sense of reciprocity by recognizing past contributions and building a relationship."},
    "Scarcity": {"Explanation": "The email implies urgency by stating that the security update is'mandatory' and that immediate action is required, suggesting that delaying could lead to potential risks or issues."},
    "Authority": {"Explanation": "The email references the sender as a member of the TechX Security Team, implying authority and the need for compliance from the recipient based on this role."},
    "Commitment/Consistency": {"Explanation": "The email references the recipient's previous actions during an internship in Paris, suggesting consistency in following security procedures and reinforcing the importance of current action."},
    "Liking": {"Explanation": "The email uses personalization and familiarity by addressing the recipient by name and mentioning their role and past experiences, which can build rapport and trust."},
    "Social proof": {"Explanation": "Not present"}
}

