    "Commitment/Consistency": {"Explanation": "The email does not reference prior behavior or choices to push further action."},
    "Liking": {"Explanation": "The email does not use personalization, flattery, or familiarity to build trust or rapport."},
    "Social proof": {"Explanation": "The email does not reference other people's participation or endorsements to build credibility or trust."}
}

